// Тикет #6aa7f009. В приложении «открыть по URL» = deep link; без APP_SCHEME тест пропускается (через меню экраны onboarding недостижимы).
import { expect } from '@wdio/globals';
import { byText } from '../../helpers/ui.ts';
import { hasDeepLinks, openRoute } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

describe('Onboarding — недоступен зарегистрированному', () => {
  afterEach(async () => { await toHome(); });

  it('OB-01 Зарегистрированный пользователь не попадает в onboarding по ссылке #6aa7f009 @prod-safe', async function () {
    if (!hasDeepLinks()) this.skip();
    // 1. По очереди открыть маршруты onboarding — каждый ведёт на главную (нижнее меню «בית», блок «תזכורות מהירות»).
    const routes = ['/level', '/summary', '/birth-date', '/dates', '/location', '/reminders', '/motivation', '/nusach', '/register', '/welcome'];
    for (const route of routes) {
      await openRoute(route);
      await (await byText('תזכורות מהירות')).waitForDisplayed({ timeout: 15000, timeoutMsg: `маршрут ${route}: нет главной` });
      await expect(byText('יצירת חשבון')).not.toBeDisplayed();
    }
  });
});
